use esp_hal::gpio::Level;
use espforge_runtime::PulseCode;

use crate::Context;

/// Two NEC-style pulse pairs: a 560µs mark and a 1690µs space, then a short
/// mark. At 38kHz the carrier is generated by the channel.
const FRAME: [PulseCode; 2] = [
    PulseCode::new(Level::High, 560, Level::Low, 1690),
    PulseCode::new(Level::High, 560, Level::Low, 560),
];

pub fn setup(ctx: &mut Context) {
    let logger = ctx.logger;
    let mut ir = device!(ctx, ir_tx);
    match ir.transmit(&FRAME) {
        Ok(()) => logger.info("RMT frame sent"),
        Err(_) => logger.info("RMT transmit failed"),
    }
}

pub fn forever(ctx: &mut Context) {
    ctx.delay.delay_ms(1000);
}
